NextCutoffDetails = {
	init: async function (app,container) {
		app = app || session.app;
		container = container || $("[component[Name=NextCuttoffDetails]]");
		app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);
		var calendarId = app.Config.Calendars.primary;
		var cutoffEvent = app.Config.Calendars.CutoffEventName;
		var expiryTime = app.Config.B2B.ExpiryTime || "23:59";
		let date = new Date();
		let yesterday = new Date(new Date(date.setDate(date.getDate() - 1)).setHours(0,0,0,0));
		var events = (await api.get("Workflow/CalendarEvent?$filter=CalendarId eq " + calendarId + " and Name eq '" + cutoffEvent + "' and Start gt " + yesterday.toISOString().split("T")[0] + "&$top=3&$orderby=Start asc")).value;
		var scheduledTasks = (await api.get("Workflow/ScheduledTask?$filter=AppId eq " + app.Id + " and NextExecution ne null")).value;
		var scheduledTaskEvents = scheduledTasks.map(s => {
			return [
				{ Id: 0, Name: s.Name, Start: s.NextExecution, End: s.NextExecution },
				{ Id: 0, Name: s.Name, Start: s.LastExecuted, End: s.LastExecuted },
			];
		}).flat();
		var calendarDataSource = events.concat(scheduledTaskEvents).map(r => {
			r.Start = new Date(r.Start);
			r.End = new Date(r.End);
			return r;
		});
		NextCutoffDetails.displayTimeUntilNextCutoff(app, events, expiryTime, container, calendarDataSource);
		NextCutoffDetails.displayOfferStats(app, container);
	},

	displayOfferStats: async function (app, container) {
		var offersInPaymentRun = (await api.get("B2B/Offer/FromSystem(SystemId='" +app.Config.B2B.SourceSystem + "')?$select=Id,FunderState,CreditorState,DebtorState,TransactionValue")).value;
		var rejectedOffers = offersInPaymentRun.filter(o=>o.DebtorState == "RejectedCancelled" || o.CreditorState == "RejectedCancelled" || o.FunderState == "RejectedCancelled");
		var paidOffers = offersInPaymentRun.filter(o => (o.DebtorState == "Paid" || o.FunderState == "Paid"));
		var acceptedOffers = offersInPaymentRun.filter(o=> (o.CreditorState == "FundingAccepted" || o.FunderState == "FundingAccepted") && rejectedOffers.filter(r => r.Id === o.Id).length === 0 && paidOffers.filter(r => r.Id === o.Id).length === 0 );
		var proposedOffers = offersInPaymentRun.filter(o=> (o.DebtorState == "Proposed" || o.FunderState == "Proposed") && rejectedOffers.filter(r => r.Id === o.Id).length === 0 && acceptedOffers.filter(r => r.Id === o.Id).length === 0 && paidOffers.filter(r => r.Id === o.Id).length === 0 );
		var totalProposed = kendo.toString(proposedOffers.map(o=>o.TransactionValue).reduce((a,b)=> a+b,0), type.moneyFormat);
		var totalAccepted = kendo.toString(acceptedOffers.map(o=>o.TransactionValue).reduce((a,b)=> a+b,0), type.moneyFormat);
		var totalRejected = kendo.toString(rejectedOffers.map(o=>o.TransactionValue).reduce((a,b)=> a+b,0), type.moneyFormat);
		var statsContainer = $("[name=offerStats]",container);
		$("a[name=proposed] > [name=value]", statsContainer).text(B2B.transactionStates["Proposed"] + " " + totalProposed + " (" + proposedOffers.length + ")");
		$("a[name=accepted] > [name=value]", statsContainer).text( window.B2B.transactionStates["FundingAccepted"] + " " + totalAccepted + " (" + acceptedOffers.length + ")");
		$("a[name=rejected] > [name=value]", statsContainer).text(window.B2B.transactionStates["RejectedCancelled"] + " " + totalRejected + " (" + rejectedOffers.length + ")");
	},

	getTimeUntilNextCutoff: function (event, expiryTime) {
		var eventStart = new Date(event.Start).toISOString().split("T")[0] + "T" + expiryTime + ":00Z";
		var dateDifference = new Date(eventStart) - new Date();
		var day = Math.floor(dateDifference / (1000 * 60 * 60 * 24));
		var hour = Math.floor((dateDifference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
		var minutes = Math.floor((dateDifference % (1000 * 60 * 60)) / (1000 * 60));
		var seconds = Math.floor((dateDifference % (1000 * 60)) / 1000);
		return {
			days:day,
			hours:hour,
			minutes:minutes,
			seconds:seconds
		};
	},

	displayTimeUntilNextCutoff: function (app, events, expiryTime, container, calendarDataSource) {
		setInterval(function(){
			var timeLeft = NextCutoffDetails.getTimeUntilNextCutoff(events[0], expiryTime);
			if(timeLeft.seconds < 0)
			{
				timeLeft = NextCutoffDetails.getTimeUntilNextCutoff(events[1], expiryTime);
			}

			$("[name=timeLeft]", container).html("<p class=countdown> [resource_description[nextcutoff]]: " + timeLeft.days + " [resource_displayname[days]] " + timeLeft.hours + " [resource_displayname[hours]] " + timeLeft.minutes + " [resource_displayname[minutes]] " + timeLeft.seconds + " [resource_displayname[seconds]] " + "</p>");
			$("[name=timeLeft]", container).off("click").on("click", (e) => NextCutoffDetails.showCalendar(e, app, events[1], calendarDataSource));
			$(".countdown", container).css("color", session.app.Config.Themes.Default.colours.text);
		},1000)
	},

	showCalendar(e, app, event, calendarDataSource) {
		e.preventDefault();
		var d = new Dialog({title: "[resource_displayname[calendar]]", width: 1200, height: 400});
		d.init(async () => {
			var calendar = await loadComponent($(d.element), "CalendarManagement");
			var endDate = new Date(event.Start);
			endDate.setDate(endDate.getDate() + 1);
			await calendar.init(app, $(".component[name=CalendarManagement]"), {
				readOnly: true, 
				fromDate: new Date(), 
				toDate: endDate,
				eventSource: calendarDataSource
			});
		});
	}
}
